definition:
export interface Environment {
	id: string;
	name: string;
	type: ENVIRONMENT_TYPE;
	created_at: string;
	updated_at: string;
}

export interface BaseModel {
	id: string;
	created_at: string;
	updated_at: string;
	created_by: string;
	updated_by: string;
	tenant_id: string;
	status: ENTITY_STATUS;
	environment_id: string;
}

export interface Metadata {
	[key: string]: string;
}

export interface SpendAlertThreshold {
	threshold: string;
	condition: 'above' | 'below';
}

export interface AlertSettingsConfig {
	critical?: SpendAlertThreshold | null;
	warning?: SpendAlertThreshold | null;
	info?: SpendAlertThreshold | null;
	alert_enabled?: boolean;
}

export interface AlertSetting extends BaseModel {
	readonly entity_type: ALERT_ENTITY_TYPE;
	readonly entity_id: string;
	readonly parent_entity_type?: ALERT_ENTITY_TYPE;
	readonly parent_entity_id?: string;
	readonly enabled: boolean;
	readonly config: AlertSettingsConfig;
}

interface Addon extends BaseModel {
	readonly name: string;
	readonly description: string;
	readonly lookup_key: string;
	readonly metadata: Metadata;
}

export interface Customer extends BaseModel {
	address_city: string;
	address_country: string;
	address_line1: string;
	address_line2: string;
	address_postal_code: string;
	address_state: string;
	email: string;
	external_id: string;
	metadata: Metadata;
	name: string;
	environment_id: string;
	timezone?: string;
}

export interface CreditGrant extends BaseModel {
	readonly credits: number;
	readonly cadence: CREDIT_GRANT_CADENCE;
	readonly metadata: Metadata;
	readonly name: string;
	readonly period?: CREDIT_GRANT_PERIOD;
	readonly period_count?: number;
	readonly plan_id?: string;
	readonly addon_id?: string;
	readonly priority?: number;
	readonly scope: CREDIT_GRANT_SCOPE;
	readonly expiration_duration?: number;
	readonly expiration_type?: CREDIT_GRANT_EXPIRATION_TYPE;
	readonly expiration_duration_unit?: CREDIT_GRANT_PERIOD_UNIT;
	readonly subscription_id?: string;
	readonly conversion_rate?: number;
	readonly topup_conversion_rate?: number;
	/** ISO date string. Present for SUBSCRIPTION-scoped grants. */
	readonly start_date?: string;
	/** ISO date string. Optional end date for the grant. */
	readonly end_date?: string;
	/** ISO date string. Anchor date for recurring credit grant applications. */
	readonly credit_grant_anchor?: string;
}

export interface CouponRules {
	[key: string]: any;
}

export interface AsyncSearchConfig<T = any> {
	// Required: Your search function (handles empty query automatically)
	searchFn: (query: string) => Promise<Array<SelectOption & { data: T }>>;

	// Optional: Override defaults
	debounceTime?: number; // Default: 300ms
	initialOptions?: SelectOption[]; // Default: fetch with empty query
}

export interface FilterField {
	field: string;
	label: string;
	fieldType: FilterFieldType;
	operators: FilterOperator[];
	options?: { value: string; label: string }[];
	enumValues?: string[];
	dataType: DataType;

	// NEW: For async fields - just add this!
	asyncConfig?: AsyncSearchConfig;
}

export interface FilterCondition {
	id: string;
	field: string;
	operator: FilterOperator;
	dataType?: DataType;

	// values option (frontend uses separate fields for convenience)
	valueString?: string;
	valueNumber?: number;
	valueArray?: Array<string>;
	valueDate?: Date;

	// future use
	valueBoolean?: boolean;
}

export interface FilterGroup {
	id: string;
	conditions: FilterCondition[];
	operator: FilterOperator;
}

export interface SortOption {
	field: string;
	label: string;
	direction?: SortDirection;
}

export interface Filters {
	expand?: string;
	limit?: number | null;
	offset?: number;
	order?: string;
	sort?: string;
}

export interface ChargeActionHandlers {
	onEditPrice: (price: Price) => void;
	onEditDetails: (price: Price) => void;
	onTerminatePrice: (price: Price) => void;
	canWritePrice: boolean;
}

export interface PriceUnit extends BaseModel {
	readonly name: string;
	readonly code: string;
	readonly symbol: string;
	readonly base_currency: string;
	readonly conversion_rate: string;
	readonly metadata: Metadata | null;
}

export interface CustomCurrencyDefinition {
	name: string;
	symbol: string;
	fiat_conversion_factors: Record<string, string>;
}

export interface CustomCurrencyConfig {
	custom_currencies: Record<string, CustomCurrencyDefinition>;
	default_fiat_currency: string;
}

export interface CustomCurrencyDraftRow {
	/** Stable React key. Codes are editable, so they cannot serve as the key. */
	id: string;
	code: string;
	name: string;
	symbol: string;
	factors: Record<string, string>;
}

export interface CustomCurrencyDraft {
	defaultFiatCurrency: string;
	fiatCurrencies: string[];
	currencies: CustomCurrencyDraftRow[];
}

export interface CurrencyOption {
	type: PRICE_UNIT_TYPE.FIAT;
	code: string;
	symbol: string;
	value: string; // Same as code for currencies
	label: string; // Currency code (e.g., "USD")
}

export interface PriceUnitOption {
	type: PRICE_UNIT_TYPE.CUSTOM;
	code: string;
	symbol: string;
	base_currency: string;
	conversion_rate: string;
	value: string; // Price unit code (e.g., "BTC")
	label: string; // Display format: "BTC (₿)" or "TOK (tokens)"
	priceUnit: PriceUnit; // Full PriceUnit object
}

export interface CurrencyPriceUnitSelection {
	type: PRICE_UNIT_TYPE;
	data: CurrencyOption | PriceUnitOption;
}

export interface Group extends BaseModel {
	readonly name: string;
	readonly lookup_key: string;
	readonly entity_type: GROUP_ENTITY_TYPE;
	readonly entity_ids: string[];
	readonly metadata: Metadata | null;
}

export interface Meter extends BaseModel {
	readonly aggregation: {
		field: string;
		expression?: string;
		type: METER_AGGREGATION_TYPE;
		multiplier?: number;
		bucket_size?: BUCKET_SIZE;
		group_by?: string;
	};
	readonly event_name: string;
	readonly filters: Array<{
		key: string;
		values: string[];
	}>;
	readonly name: string;
	readonly reset_usage: METER_USAGE_RESET_PERIOD;
}

export interface AlertThreshold {
	threshold: string;
	condition: 'above' | 'below';
}

export interface AlertSettings {
	critical?: AlertThreshold | null;
	warning?: AlertThreshold | null;
	info?: AlertThreshold | null;
	alert_enabled?: boolean;
}

export interface FeatureReportingUnit {
	unit_singular?: string;
	unit_plural?: string;
	conversion_rate?: string;
}

export interface Feature extends BaseModel {
	readonly name: string;
	readonly description: string;
	readonly lookup_key?: string;
	readonly meter_id: string;
	readonly metadata: Metadata;
	readonly type: FEATURE_TYPE;
	readonly tenant_id: string;
	readonly unit_plural: string;
	readonly unit_singular: string;
	readonly reporting_unit?: {
		unit_singular: string;
		unit_plural: string;
		conversion_rate?: string;
	};
	readonly meter?: Meter;
	readonly alert_settings?: AlertSettings;
	readonly group_id?: string;
	readonly group?: Group;
	readonly config_value?: JsonObject;
}

export interface Entitlement extends BaseModel {
	readonly feature: Feature;
	readonly feature_id: string;
	readonly feature_type: string;
	readonly is_enabled: boolean;
	readonly is_soft_limit: boolean;
	readonly entity_type: ENTITLEMENT_ENTITY_TYPE;
	readonly entity_id: string;
	readonly static_value: string;
	readonly tenant_id: string;
	readonly usage_limit: number | null;
	readonly usage_reset_period: ENTITLEMENT_USAGE_RESET_PERIOD | null;
	readonly display_order?: number;
	readonly parent_entitlement_id?: string;
	/** ISO date string. Optional start date for the entitlement. */
	readonly start_date?: string;
	/** ISO date string. Optional end date for the entitlement. */
	readonly end_date?: string;
	readonly config_value?: JsonObject | null;
}

export interface PlanPriceSyncStatus {
	readonly current_sequence: number;
	readonly unsynced_subscription_count: number;
	readonly synced: boolean;
}

export interface Plan extends BaseModel {
	readonly description: string;
	readonly lookup_key: string;
	readonly name: string;
	readonly metadata?: Metadata;
	readonly display_order?: number;
	readonly price_sync_status?: PlanPriceSyncStatus;
}

export interface BackendFilterValue {
	string?: string;
	number?: number;
	boolean?: boolean;
	date?: string;
	array?: string[];
}

export interface TypedBackendFilter {
	field: string;
	operator: BackendFilterOperator;
	data_type: DataType;
	value: BackendFilterValue;
}

export interface TypedBackendQueryPayload {
	filters: TypedBackendFilter[];
}

export interface TypedBackendSort {
	field: string;
	direction: SortDirection;
}

export interface TypedBackendSortPayload {
	sorts: TypedBackendSort[];
}

export interface TypedBackendQueryWithSortPayload {
	filters: TypedBackendFilter[];
	sorts: TypedBackendSort[];
}

export interface ExtractMetadataFromTypedFiltersResult {
	/** Filters with metadata pseudo-filters removed (safe for generic search APIs). */
	filters: TypedBackendFilter[];
	/** Present only when at least one non-blank key/value pair was parsed. */
	metadata?: Record<string, string>;
}

export interface QueryFilter {
	limit?: number | null;
	offset?: number;
	status?: ENTITY_STATUS;
	sort?: string;
	order?: string;
	expand?: string;
}

export interface TimeRangeFilter {
	start_time?: string;
	end_time?: string;
}

export interface CreateBulkPriceRequest {
	items: CreatePriceRequest[];
}

export interface GetAllPricesResponse extends Pagination {
	items: PriceResponse[];
}

export interface SearchPricesRequest {
	/** Optional: scope by entity (e.g. plan). When omitted, scope via filters (e.g. group_id eq). */
	entity_ids?: string[];
	entity_type?: PRICE_ENTITY_TYPE;
	filters?: TypedBackendFilter[];
	sorts?: TypedBackendSort[];
	allow_expired_prices?: boolean;
	expand?: string;
	limit?: number | null;
	offset?: number;
}

export interface SearchPricesResponse {
	items: PriceResponse[];
	pagination?: { total?: number; limit?: number; offset?: number };
}

export interface PriceFilter extends QueryFilter, TimeRangeFilter {
	price_ids?: string[];
	entity_type?: PRICE_ENTITY_TYPE;
	entity_ids?: string[];
	subscription_id?: string;
	parent_price_id?: string;
	meter_ids?: string[];
	start_date_lt?: string; // ISO date string
}

export interface CreatePriceRequest {
	amount?: string;
	currency: string;
	plan_id?: string; // TODO: This is deprecated and will be removed in the future
	entity_type: PRICE_ENTITY_TYPE;
	entity_id: string;
	type: PRICE_TYPE;
	price_unit_type: PRICE_UNIT_TYPE;
	billing_period?: BILLING_PERIOD;
	billing_period_count?: number; // defaults to 1
	billing_model: BILLING_MODEL;
	meter_id?: string;
	filter_values?: Record<string, string[]>;
	lookup_key?: string;
	invoice_cadence: INVOICE_CADENCE;
	trial_period_days?: number;
	description?: string;
	display_name?: string;
	metadata?: Metadata;
	tier_mode?: TIER_MODE;
	tiers?: CreatePriceTier[];
	transform_quantity?: TransformQuantity;
	// PriceUnitConfig is required when price_unit_type is CUSTOM
	price_unit_config?: PriceUnitConfig;
	start_date?: string; // ISO date string
	end_date?: string; // ISO date string
	group_id?: string;
	min_quantity?: number;
	/** Windows usage into fixed-size buckets before aggregation (USAGE prices only). Omit for no bucketing. */
	bucket_size?: PriceBucketSize;
}

export interface GetPriceResponse extends Price {
	plan: Plan;
	addon: Addon;
	feature: Feature;
	meter: Meter;
}

export interface CreatePriceTier {
	// up_to is the quantity up to which this tier applies. It is null for the last tier.
	// IMPORTANT: Tier boundaries are INCLUSIVE.
	// - If up_to is 1000, then quantity less than or equal to 1000 belongs to this tier
	// - This behavior is consistent across both VOLUME and SLAB tier modes
	up_to?: number | null;
	unit_amount: string;
	flat_amount?: string;
}

export interface PriceUnitConfig {
	// Amount is the price amount in the custom price unit (optional)
	// Required when billing_model is FLAT_FEE or PACKAGE with custom price unit
	amount?: string;
	/**
	 * The price unit code (3 characters, e.g., "BTC", "TOK", "CRD")
	 * This is the unique identifier for the price unit, not the full PriceUnit object
	 * Required when using custom price unit type
	 */
	price_unit: string;
	// PriceUnitTiers are the pricing tiers for custom price units
	// Required when billing_model is TIERED with custom price unit
	price_unit_tiers?: CreatePriceTier[];
}

export interface TransformQuantity {
	divide_by: number;
	round?: 'up' | 'down';
}

export interface CreateBulkPriceResponse {
	items: PriceResponse[];
}

export interface PriceResponse extends Price {
	pricing_unit?: PriceUnit;
	meter?: Meter;
	plan?: Plan;
	addon?: Addon;
}

export interface DeletePriceRequest {
	end_date?: string; // ISO date string
}

export interface CostBreakup {
	// EffectiveUnitCost is the per-unit cost based on the applicable tier
	effective_unit_cost: string;
	// SelectedTierIndex is the index of the tier that was applied (-1 if no tiers)
	selected_tier_index: number;
	// TierUnitAmount is the unit amount of the selected tier
	tier_unit_amount: string;
	// FinalCost is the total cost for the quantity
	final_cost: string;
}

export interface UpdatePriceRequest {
	// Non-critical fields (can be updated directly)
	lookup_key?: string;
	description?: string;
	metadata?: Metadata;
	display_name?: string;
	effective_from?: string; // ISO date string

	// Critical fields (require creating a new price)
	billing_model?: BILLING_MODEL;
	amount?: string;
	tier_mode?: TIER_MODE;
	tiers?: CreatePriceTier[];
	transform_quantity?: TransformQuantity;

	// PriceUnitAmount is the price unit amount (for CUSTOM price unit type, FLAT_FEE/PACKAGE billing models)
	price_unit_amount?: string;

	// PriceUnitTiers are the price unit tiers (for CUSTOM price unit type, TIERED billing model)
	price_unit_tiers?: CreatePriceTier[];

	// GroupID is the id of the group to update the price in
	group_id?: string;

	/**
	 * Changing this creates a new price (parent_price_id points at the old one, which is end-dated)
	 * rather than patching in place - callers must re-fetch after a successful update instead of
	 * merging the response into existing state. Send BUCKET_SIZE_NONE (the literal string "none")
	 * to remove bucketing from the price entirely; omit the field to leave it unchanged.
	 */
	bucket_size?: PriceBucketSize | typeof BUCKET_SIZE_NONE;
}

export interface LineItemCommitmentConfig {
	// CommitmentAmount is the minimum amount committed for this line item
	commitment_amount?: number;

	// CommitmentQuantity is the minimum quantity committed for this line item
	commitment_quantity?: number;

	// CommitmentType specifies whether commitment is based on amount or quantity
	commitment_type?: CommitmentType;

	// OverageFactor is a multiplier applied to usage beyond the commitment
	overage_factor?: number;

	// EnableTrueUp determines if true-up fee should be applied when usage is below commitment
	enable_true_up?: boolean;

	// IsWindowCommitment determines if commitment is applied per window (e.g., per day) rather than per billing period
	is_window_commitment?: boolean;

	// CommitmentDuration specifies the duration period for the commitment (e.g., ANNUAL, MONTHLY)
	// If not set, defaults to the subscription's billing period
	commitment_duration?: BILLING_PERIOD;

	// CommitmentTimeBuckets restricts commitment application to specific UTC time-of-day windows.
	// Requires is_window_commitment=true.
	commitment_time_buckets?: CommitmentTimeBucket[];
}

export interface ExtendedAddon extends Addon {
	prices: Price[];
	entitlements: Entitlement[];
}

export interface CreateAddonRequest {
	name: string;
	lookup_key: string;
	description?: string;
	metadata?: Metadata;
}

export interface AddonResponse extends Addon {
	prices: Price[];
	entitlements: Entitlement[];
}

export interface UpdateAddonRequest {
	name?: string;
	description?: string;
	metadata?: Metadata;
}

export interface AddAddonToSubscriptionRequest {
	addon_id: string;
	start_date?: string;
	cadence?: ADDON_CADENCE;
	proration_behavior?: ADDON_PRORATION_BEHAVIOR;
	metadata?: Metadata;
	line_item_commitments?: LineItemCommitmentsMap;
	// Per-price overrides for this addon's prices (price_id must belong to the addon).
	override_line_items?: OverrideLineItemRequest[];
}

export interface GetAddonsPayload {
	end_time?: string;
	expand?: string;
	addon_ids?: string[];
	limit?: number;
	lookup_key?: string;
	offset?: number;
	order?: string;
	sort?: string;
	start_time?: string;
	status?: string;
	lookup_keys?: string[];
}

export interface GetAddonsResponse extends Pagination {
	items: AddonResponse[];
	pagination: Pagination;
}

export interface GetAddonByFilterPayload extends Pagination {
	filters: TypedBackendFilter[];
	sort: TypedBackendSort[];
}

export interface AddonFilter extends Omit<QueryFilter, 'sort'>, TimeRangeFilter {
	filters?: FilterCondition[];
	sort?: SortOption[];
	addon_ids?: string[];
	lookup_keys?: string[];
}

export interface User {
	id: string;
	tenant: {
		id: string;
		name: string;
		billing_details: {
			address: {
				address_line1: string;
				address_line2: string;
				address_city: string;
				address_state: string;
				address_postal_code: string;
				address_country: string;
			};
		};
		status: string;
		created_at: string;
		updated_at: string;
	};
	email: string;
	name?: string;
	type?: 'user' | 'service_account';
	roles?: string[];
	metadata?: Record<string, string>;
}

export type WalletTransaction = {
	readonly amount: number;
	readonly balance_after: number;
	readonly balance_before: number;
	readonly created_at: string;
	readonly description: string;
	readonly id: string;
	readonly metadata: Metadata;
	readonly reference_id: string;
	readonly reference_type: string;
	readonly transaction_status: string;
	readonly type: string;
	readonly wallet_id: string;
	readonly credit_amount: number;
	readonly transaction_reason: string;
	readonly expiry_date: string;
	readonly priority?: number;
	readonly customer_id?: string;
	readonly created_by?: string;
	readonly customer?: Customer;
	readonly currency?: string;
	readonly created_by_user?: User;
};

export interface Coupon extends BaseModel {
	name: string;
	redeem_after?: string;
	redeem_before?: string;
	max_redemptions?: number;
	total_redemptions: number;
	rules?: CouponRules;
	amount_off?: string;
	percentage_off?: string;
	type: COUPON_TYPE;
	cadence: COUPON_CADENCE;
	duration_in_periods?: number;
	currency: string;
	coupon_code?: string;
	metadata?: Metadata;
}

export type Duration = {
	value: number;
	unit: DurationUnit;
};

export type AutoTopup = {
	enabled: boolean;
	threshold: string;
	amount: string;
	invoicing: boolean;
	/** Omit/null/undefined = no cooloff. Send `{ value: 0, unit: 'second' }` on PUT to clear. */
	cooldown?: Duration | null;
};

export interface WalletAlertThreshold {
	threshold: string;
	condition: 'above' | 'below';
}

export interface WalletAlertSettings {
	critical?: WalletAlertThreshold | null;
	warning?: WalletAlertThreshold | null;
	info?: WalletAlertThreshold | null;
	alert_enabled?: boolean;
	alert_threshold_type?: WalletAlertThresholdType;
}

export interface WalletAlertDraft {
	alert_enabled: boolean;
	alert_threshold_type: WalletAlertThresholdType;
	absolute: WalletAlertLevels;
	percentage: WalletAlertLevels;
}

export interface Wallet extends BaseModel {
	readonly balance: number;
	readonly name: string;
	readonly currency: string;
	readonly customer_id: string;
	readonly metadata: Metadata;
	readonly wallet_status: WALLET_STATUS;
	readonly wallet_type: WALLET_TYPE;
	readonly conversion_rate: number;
	readonly topup_conversion_rate?: number;
	readonly meter: Meter;
	readonly alert_settings?: WalletAlertSettings;
	readonly alert_state?: WalletAlertState;
	readonly auto_topup?: AutoTopup;
}

export interface CreateAlertSettingsRequest {
	entity_type: ALERT_ENTITY_TYPE;
	entity_id: string;
	parent_entity_type?: ALERT_ENTITY_TYPE;
	parent_entity_id?: string;
	config: AlertSettingsConfig;
}

export interface UpdateAlertSettingsRequest {
	config: AlertSettingsConfig;
}

export interface AlertSettingsFilter extends QueryFilter {
	entity_type?: ALERT_ENTITY_TYPE;
	entity_id?: string;
	entity_ids?: string[];
	parent_entity_type?: ALERT_ENTITY_TYPE;
	parent_entity_id?: string;
	parent_entity_ids?: string[];
	enabled?: boolean;
}

export interface SearchAlertSettingsResponse {
	items: AlertSettingResponse[];
	pagination?: { total?: number; limit?: number; offset?: number };
}

export interface MeterFilter {
	key: string;
	values: string[];
}

export interface MeterAggregation {
	type: METER_AGGREGATION_TYPE;
	field?: string;
	// CEL expression evaluated per event to compute the quantity. Mutually
	// exclusive with `field`; only allowed for SUM, AVG, MAX, LATEST.
	expression?: string;
	multiplier?: number;
	bucket_size?: BUCKET_SIZE;
	group_by?: string;
}

export interface CreateMeterRequest {
	name: string;
	event_name: string;
	aggregation: MeterAggregation;
	reset_usage: METER_USAGE_RESET_PERIOD;
	filters?: MeterFilter[];
}

export interface UpdateMeterRequest {
	filters?: MeterFilter[];
}

export interface GetAllMetersResponse {
	items: Meter[];
	pagination: Pagination;
}

export interface ListMetersResponse {
	items: MeterResponse[];
	pagination: Pagination;
}

export interface ReportingUnit {
	unit_singular: string;
	unit_plural: string;
	conversion_rate: string;
}

export interface CreateFeatureRequest {
	name: string;
	description?: string;
	lookup_key?: string;
	type: FEATURE_TYPE;
	meter_id?: string;
	meter?: CreateMeterRequest;
	metadata?: Metadata;
	unit_singular?: string;
	unit_plural?: string;
	reporting_unit?: ReportingUnit;
	alert_settings?: AlertSettings;
	group_id?: string;
	config_value?: JsonObject;
}

export interface UpdateFeatureRequest {
	name?: string;
	description?: string;
	metadata?: Metadata;
	unit_singular?: string;
	unit_plural?: string;
	reporting_unit?: ReportingUnit;
	filters?: MeterFilter[];
	alert_settings?: AlertSettings;
	/** Set to empty string to clear the group. */
	group_id?: string;
	config_value?: JsonObject;
}

export type FeatureFormData = Omit<CreateFeatureRequest, 'name' | 'type' | 'meter'> & {
	name?: string;
	type?: FEATURE_TYPE;
	meter?: Partial<CreateMeterRequest>;
	_rawConfigPairs?: Array<{ key: string; value: string }>;
};

export interface FeatureResponse extends Feature {
	meter?: Meter;
}

export interface ListFeaturesResponse {
	items: FeatureResponse[];
	pagination: Pagination;
}

export interface FeatureFilter {
	limit?: number;
	offset?: number;
	expand?: string;
	order?: string;
	sort?: string;
	// Feature-specific filter fields
	feature_ids?: string[];
	meter_ids?: string[];
	lookup_key?: string;
	lookup_keys?: string[];
	name_contains?: string;
	status?: ENTITY_STATUS;
	start_time?: string;
	end_time?: string;
}

export interface GetFeaturesPayload {
	end_time?: string;
	expand?: string;
	feature_ids?: string[];
	meter_ids?: string[];
	limit?: number;
	lookup_key?: string;
	lookup_keys?: string[];
	offset?: number;
	order?: string;
	sort?: string;
	name_contains?: string;
	start_time?: string;
	status?: ENTITY_STATUS;
}

export interface GetFeaturesResponse {
	items: Feature[];
	pagination: Pagination;
}

export interface GetFeatureByFilterPayload extends Pagination {
	filters: TypedBackendFilter[];
	sort: TypedBackendSort[];
}

export interface UpdateFeaturePayload extends Partial<Feature> {
	filters?: MeterFilter[];
}

export interface GetConnectionsPayload {
	status?: string;
	provider_type?: CONNECTION_PROVIDER_TYPE;
	limit?: number;
	offset?: number;
}

export interface GetConnectionsResponse {
	connections: Connection[];
	total: number;
	limit: number;
	offset: number;
}

export interface CreateConnectionPayload {
	name: string;
	provider_type: CONNECTION_PROVIDER_TYPE;
	metadata?: Record<string, string>;
	encrypted_secret_data:
		| {
				provider_type: CONNECTION_PROVIDER_TYPE.STRIPE;
				account_id?: string;
				publishable_key?: string;
				secret_key?: string;
				webhook_secret?: string;
		  }
		| {
				provider_type: CONNECTION_PROVIDER_TYPE.RAZORPAY;
				key_id?: string;
				secret_key?: string;
				webhook_secret?: string;
		  }
		| {
				provider_type: CONNECTION_PROVIDER_TYPE.S3;
